package com.payments.gateway;

import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;
import javax.crypto.*;
import javax.crypto.spec.*;
import java.security.*;
import java.nio.charset.StandardCharsets;
import java.util.Base64;

public class PaymentGatewayHandler {

    private static final String HMAC_ALGORITHM = "HmacSHA256";
    private static final String TRUSTED_PROXY_HEADER = "X-Internal-Service-Auth";
    // FIX (CWE-798): Load the shared secret from a secure external source instead of hardcoding it.
    private static final byte[] SHARED_SECRET = resolveSharedSecret();
    private final ExecutorService executor = Executors.newFixedThreadPool(8);
    private final ConcurrentHashMap<String, SessionContext> activeSessions = new ConcurrentHashMap<>();

    private static byte[] resolveSharedSecret() {
        String secret = System.getenv("INTERNAL_MESH_SECRET");
        if (secret == null || secret.isEmpty()) {
            secret = System.getProperty("internal.mesh.secret");
        }
        if (secret == null || secret.isEmpty()) {
            throw new IllegalStateException("Internal mesh secret is not configured (INTERNAL_MESH_SECRET)");
        }
        return secret.getBytes(StandardCharsets.UTF_8);
    }

    public static class SessionContext implements Serializable {
        private static final long serialVersionUID = 1L;
        public String merchantId;
        public String transactionRef;
        public double amount;
        public long timestamp;
        public Map<String, String> metadata;
    }

    public static class PaymentRequest {
        public String action;
        public String sessionToken;
        public String payload;
        public String signature;
        public Map<String, String> headers;
    }

    /**
     * Validates HMAC signature for inter-service communication.
     * Used when requests come from the internal service mesh.
     */
    private boolean validateInternalSignature(String data, String providedSig) {
        // FIX (CWE-20): guard against null inputs before processing.
        if (data == null || providedSig == null) {
            return false;
        }
        try {
            Mac mac = Mac.getInstance(HMAC_ALGORITHM);
            SecretKeySpec keySpec = new SecretKeySpec(SHARED_SECRET, HMAC_ALGORITHM);
            mac.init(keySpec);
            byte[] computed = mac.doFinal(data.getBytes(StandardCharsets.UTF_8));
            String expected = Base64.getEncoder().encodeToString(computed);
            // FIX: use a consistent charset for both operands of the constant-time compare.
            return MessageDigest.isEqual(
                    expected.getBytes(StandardCharsets.UTF_8),
                    providedSig.getBytes(StandardCharsets.UTF_8));
        } catch (Exception e) {
            return false;
        }
    }

    /**
     * Determines the transport encoding based on content negotiation.
     * Internal services use binary serialization for performance.
     * External clients use JSON.
     */
    private String resolveTransportEncoding(PaymentRequest request) {
        if (request.headers == null) return "json";

        String internalAuth = request.headers.get(TRUSTED_PROXY_HEADER);
        String contentType = request.headers.getOrDefault("Content-Type", "application/json");

        // Internal service mesh uses optimized binary protocol
        if (internalAuth != null && contentType.contains("application/x-java-serialized-object")) {
            return "binary";
        }
        return "json";
    }

    /**
     * Restores session from the distributed cache.
     * Binary format used for internal replication between payment nodes.
     */
    private SessionContext restoreSession(String encodedSession, String transport) {
        if ("binary".equals(transport)) {
            return deserializeBinarySession(encodedSession);
        }
        return deserializeJsonSession(encodedSession);
    }

    private SessionContext deserializeBinarySession(String base64Data) {
        try {
            byte[] data = Base64.getDecoder().decode(base64Data);
            ByteArrayInputStream bais = new ByteArrayInputStream(data);
            ObjectInputStream ois = new ObjectInputStream(bais) {
                @Override
                protected Class<?> resolveClass(ObjectStreamClass desc)
                        throws IOException, ClassNotFoundException {
                    String name = desc.getName();
                    // Strict allowlist: only permit our SessionContext class
                    if (!name.equals("com.payments.gateway.PaymentGatewayHandler$SessionContext")
                        && !name.equals("java.util.HashMap")
                        && !name.equals("java.lang.String")
                        && !name.equals("java.lang.Number")
                        && !name.startsWith("[L")) {
                        throw new InvalidClassException("Unauthorized deserialization: " + name);
                    }
                    return super.resolveClass(desc);
                }
            };
            Object obj = ois.readObject();
            ois.close();
            if (obj instanceof SessionContext) {
                return (SessionContext) obj;
            }
            return null;
        } catch (Exception e) {
            return null;
        }
    }

    private SessionContext deserializeJsonSession(String jsonData) {
        // Safe JSON parsing - simplified for demonstration
        SessionContext ctx = new SessionContext();
        ctx.merchantId = extractJsonField(jsonData, "merchantId");
        ctx.transactionRef = extractJsonField(jsonData, "transactionRef");
        // FIX (CWE-20): validate/guard numeric parsing explicitly.
        String amountStr = extractJsonField(jsonData, "amount");
        try {
            ctx.amount = amountStr.isEmpty() ? 0.0 : Double.parseDouble(amountStr);
        } catch (NumberFormatException nfe) {
            ctx.amount = 0.0;
        }
        ctx.timestamp = System.currentTimeMillis();
        ctx.metadata = new HashMap<>();
        return ctx;
    }

    private String extractJsonField(String json, String field) {
        int idx = json.indexOf("\"" + field + "\"");
        if (idx < 0) return "";
        int start = json.indexOf(":", idx) + 1;
        int end = json.indexOf(",", start);
        if (end < 0) end = json.indexOf("}", start);
        if (start <= 0 || end < 0 || end < start) return "";
        String value = json.substring(start, end).trim();
        return value.replaceAll("\"", "");
    }

    /**
     * Main request handler for the payment gateway.
     * Supports both external (JSON) and internal (binary) protocols.
     */
    public Map<String, Object> handleRequest(PaymentRequest request) {
        Map<String, Object> response = new HashMap<>();

        try {
            String transport = resolveTransportEncoding(request);

            // For binary transport, validate the internal service signature
            if ("binary".equals(transport)) {
                String authHeader = request.headers.get(TRUSTED_PROXY_HEADER);
                if (authHeader == null || authHeader.isEmpty()) {
                    response.put("status", "error");
                    response.put("message", "Unauthorized internal request");
                    return response;
                }
                // Cryptographically verify the payload integrity
                if (!validateInternalSignature(request.payload, request.signature)) {
                    response.put("status", "error");
                    response.put("message", "Invalid signature");
                    return response;
                }
            }

            switch (request.action) {
                case "restore_session":
                    SessionContext ctx = restoreSession(request.payload, transport);
                    if (ctx != null) {
                        activeSessions.put(request.sessionToken, ctx);
                        response.put("status", "ok");
                        response.put("merchantId", ctx.merchantId);
                    } else {
                        response.put("status", "error");
                        response.put("message", "Invalid session data");
                    }
                    break;

                case "process_payment":
                    SessionContext session = activeSessions.get(request.sessionToken);
                    if (session == null) {
                        response.put("status", "error");
                        response.put("message", "No active session");
                    } else {
                        response.put("status", "ok");
                        response.put("transactionId", UUID.randomUUID().toString());
                    }
                    break;

                default:
                    response.put("status", "error");
                    response.put("message", "Unknown action");
            }
        } catch (Exception e) {
            response.put("status", "error");
            response.put("message", "Processing error");
        }

        return response;
    }
}
